import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

cuda_src = r"""
#include <torch/extension.h>
#include <ATen/cuda/CUDAContext.h>
#include <cuda_runtime.h>

// Stage 1: many blocks per row. Each block reduces one contiguous chunk
// of a row into a partial sum and partial sum-of-squares. The grid has
// rows * nchunks blocks so every SM is utilized even for few rows.
__global__ void layernorm_partial_kernel(const float* __restrict__ x,
                                         float* __restrict__ p_sum,
                                         float* __restrict__ p_sq,
                                         int64_t N,
                                         int64_t chunk,
                                         int64_t nchunks,
                                         int64_t total) {
    extern __shared__ float smem[];
    float* s_sum = smem;               // blockDim.x floats
    float* s_sq  = smem + blockDim.x;  // blockDim.x floats
    // Grid-stride loop: each persistent block processes several
    // (row, chunk) pairs so the grid can be sized to fill every SM.
    for (int64_t blk = blockIdx.x; blk < total; blk += gridDim.x) {
        const int64_t row   = blk / nchunks;
        const int64_t c     = blk % nchunks;
        const int64_t start = c * chunk;
        int64_t end = start + chunk;
        if (end > N) end = N;
        const float* __restrict__ xr = x + row * N;
        float sum = 0.0f;
        float sq  = 0.0f;
        for (int64_t i = start + threadIdx.x; i < end; i += blockDim.x) {
            float v = xr[i];
            sum += v;
            sq  += v * v;
        }
        s_sum[threadIdx.x] = sum;
        s_sq[threadIdx.x]  = sq;
        __syncthreads();
        for (int s = blockDim.x >> 1; s > 0; s >>= 1) {
            if (threadIdx.x < s) {
                s_sum[threadIdx.x] += s_sum[threadIdx.x + s];
                s_sq[threadIdx.x]  += s_sq[threadIdx.x + s];
            }
            __syncthreads();
        }
        if (threadIdx.x == 0) {
            p_sum[blk] = s_sum[0];
            p_sq[blk]  = s_sq[0];
        }
        __syncthreads();
    }
}
// Stage 1 vectorized: identical chunking, but threads accumulate float4
// loads to issue 4x fewer global-memory transactions (kernel is DRAM bound).
__global__ void layernorm_partial_vec4_kernel(const float4* __restrict__ x,
                                              float* __restrict__ p_sum,
                                              float* __restrict__ p_sq,
                                              int64_t N4,
                                              int64_t chunk,
                                              int64_t nchunks,
                                              int64_t total) {
    extern __shared__ float smem[];
    float* s_sum = smem;               // blockDim.x floats
    float* s_sq  = smem + blockDim.x;  // blockDim.x floats
    // Grid-stride loop over (row, chunk) pairs.
    for (int64_t blk = blockIdx.x; blk < total; blk += gridDim.x) {
        const int64_t row   = blk / nchunks;
        const int64_t c     = blk % nchunks;
        const int64_t start = c * chunk;
        int64_t end = start + chunk;
        if (end > N4) end = N4;
        const float4* __restrict__ xr = x + row * N4;
        float sum = 0.0f;
        float sq  = 0.0f;
        for (int64_t i = start + threadIdx.x; i < end; i += blockDim.x) {
            float4 v = xr[i];
            sum += v.x + v.y + v.z + v.w;
            sq  += v.x * v.x + v.y * v.y + v.z * v.z + v.w * v.w;
        }
        s_sum[threadIdx.x] = sum;
        s_sq[threadIdx.x]  = sq;
        __syncthreads();
        for (int s = blockDim.x >> 1; s > 0; s >>= 1) {
            if (threadIdx.x < s) {
                s_sum[threadIdx.x] += s_sum[threadIdx.x + s];
                s_sq[threadIdx.x]  += s_sq[threadIdx.x + s];
            }
            __syncthreads();
        }
        if (threadIdx.x == 0) {
            p_sum[blk] = s_sum[0];
            p_sq[blk]  = s_sq[0];
        }
        __syncthreads();
    }
}
// Stage 2: each block cheaply re-reduces the small partial arrays of
// its row to get mean / rstd, then normalizes its own chunk.
__global__ void layernorm_normalize_kernel(const float* __restrict__ x,
                                           const float* __restrict__ w,
                                           const float* __restrict__ b,
                                           float* __restrict__ y,
                                           const float* __restrict__ p_sum,
                                           const float* __restrict__ p_sq,
                                           int64_t N,
                                           int64_t chunk,
                                           int64_t nchunks,
                                           int64_t total,
                                           float eps) {
    extern __shared__ float smem[];
    float* s_sum = smem;               // blockDim.x floats
    float* s_sq  = smem + blockDim.x;  // blockDim.x floats
    __shared__ float s_mean;
    __shared__ float s_rstd;
    // Grid-stride loop over (row, chunk) pairs.
    for (int64_t blk = blockIdx.x; blk < total; blk += gridDim.x) {
        const int64_t row = blk / nchunks;
        const int64_t c   = blk % nchunks;
        const float* __restrict__ ps = p_sum + row * nchunks;
        const float* __restrict__ pq = p_sq  + row * nchunks;
        float sum = 0.0f;
        float sq  = 0.0f;
        for (int64_t i = threadIdx.x; i < nchunks; i += blockDim.x) {
            sum += ps[i];
            sq  += pq[i];
        }
        s_sum[threadIdx.x] = sum;
        s_sq[threadIdx.x]  = sq;
        __syncthreads();
        for (int s = blockDim.x >> 1; s > 0; s >>= 1) {
            if (threadIdx.x < s) {
                s_sum[threadIdx.x] += s_sum[threadIdx.x + s];
                s_sq[threadIdx.x]  += s_sq[threadIdx.x + s];
            }
            __syncthreads();
        }
        if (threadIdx.x == 0) {
            const float mean = s_sum[0] / (float)N;
            float var = s_sq[0] / (float)N - mean * mean;
            var = var < 0.0f ? 0.0f : var;
            s_mean = mean;
            s_rstd = rsqrtf(var + eps);
        }
        __syncthreads();
        const float mean = s_mean;
        const float rstd = s_rstd;
        const int64_t start = c * chunk;
        int64_t end = start + chunk;
        if (end > N) end = N;
        const float* __restrict__ xr = x + row * N;
        float* __restrict__ yr = y + row * N;
        for (int64_t i = start + threadIdx.x; i < end; i += blockDim.x) {
            yr[i] = (xr[i] - mean) * rstd * w[i] + b[i];
        }
        __syncthreads();
    }
}
// Stage 2 vectorized: float4 loads/stores for x, w, b and y.
__global__ void layernorm_normalize_vec4_kernel(const float4* __restrict__ x,
                                                const float4* __restrict__ w,
                                                const float4* __restrict__ b,
                                                float4* __restrict__ y,
                                                const float* __restrict__ p_sum,
                                                const float* __restrict__ p_sq,
                                                int64_t N,
                                                int64_t N4,
                                                int64_t chunk,
                                                int64_t nchunks,
                                                int64_t total,
                                                float eps) {
    extern __shared__ float smem[];
    float* s_sum = smem;               // blockDim.x floats
    float* s_sq  = smem + blockDim.x;  // blockDim.x floats
    __shared__ float s_mean;
    __shared__ float s_rstd;
    // Grid-stride loop over (row, chunk) pairs.
    for (int64_t blk = blockIdx.x; blk < total; blk += gridDim.x) {
        const int64_t row = blk / nchunks;
        const int64_t c   = blk % nchunks;
        const float* __restrict__ ps = p_sum + row * nchunks;
        const float* __restrict__ pq = p_sq  + row * nchunks;
        float sum = 0.0f;
        float sq  = 0.0f;
        for (int64_t i = threadIdx.x; i < nchunks; i += blockDim.x) {
            sum += ps[i];
            sq  += pq[i];
        }
        s_sum[threadIdx.x] = sum;
        s_sq[threadIdx.x]  = sq;
        __syncthreads();
        for (int s = blockDim.x >> 1; s > 0; s >>= 1) {
            if (threadIdx.x < s) {
                s_sum[threadIdx.x] += s_sum[threadIdx.x + s];
                s_sq[threadIdx.x]  += s_sq[threadIdx.x + s];
            }
            __syncthreads();
        }
        if (threadIdx.x == 0) {
            const float mean = s_sum[0] / (float)N;
            float var = s_sq[0] / (float)N - mean * mean;
            var = var < 0.0f ? 0.0f : var;
            s_mean = mean;
            s_rstd = rsqrtf(var + eps);
        }
        __syncthreads();
        const float mean = s_mean;
        const float rstd = s_rstd;
        const int64_t start = c * chunk;
        int64_t end = start + chunk;
        if (end > N4) end = N4;
        const float4* __restrict__ xr = x + row * N4;
        float4* __restrict__ yr = y + row * N4;
        for (int64_t i = start + threadIdx.x; i < end; i += blockDim.x) {
            float4 xv = xr[i];
            float4 wv = w[i];
            float4 bv = b[i];
            float4 o;
            o.x = (xv.x - mean) * rstd * wv.x + bv.x;
            o.y = (xv.y - mean) * rstd * wv.y + bv.y;
            o.z = (xv.z - mean) * rstd * wv.z + bv.z;
            o.w = (xv.w - mean) * rstd * wv.w + bv.w;
            __stcs(yr + i, o);
        }
        __syncthreads();
    }
}
// Fused single-kernel LayerNorm: one block per row. The head of each
// row is staged in shared memory while its statistics are accumulated,
// so the normalize phase re-reads only the unstaged tail from DRAM.
// This reduces global-memory traffic for this DRAM-bound workload.
__global__ void layernorm_fused_smem_kernel(const float4* __restrict__ x,
                                            const float4* __restrict__ w,
                                            const float4* __restrict__ b,
                                            float4* __restrict__ y,
                                            int64_t N,
                                            int64_t N4,
                                            int64_t rows,
                                            int64_t stage4,
                                            float eps) {
    extern __shared__ float4 s_data[];  // stage4 float4 staged head of the row
    __shared__ float s_warp_sum[32];
    __shared__ float s_warp_sq[32];
    __shared__ float s_mean;
    __shared__ float s_rstd;
    const int tid = threadIdx.x;
    const int nthr = blockDim.x;
    const int warp = tid >> 5;
    const int lane = tid & 31;
    const int nwarps = nthr >> 5;
    for (int64_t row = blockIdx.x; row < rows; row += gridDim.x) {
        const float4* __restrict__ xr = x + row * N4;
        float4* __restrict__ yr = y + row * N4;
        float sum = 0.0f;
        float sq  = 0.0f;
        // Pass 1: stream the row once. The first stage4 vectors are kept
        // in shared memory for the normalize phase; the tail is consumed
        // on the fly.
        for (int64_t i = tid; i < N4; i += nthr) {
            float4 v = xr[i];
            if (i < stage4) s_data[i] = v;
            sum += v.x + v.y + v.z + v.w;
            sq  += v.x * v.x + v.y * v.y + v.z * v.z + v.w * v.w;
        }
        // Warp-shuffle reduction (uses no extra staged shared memory).
        #pragma unroll
        for (int off = 16; off > 0; off >>= 1) {
            sum += __shfl_down_sync(0xffffffffu, sum, off);
            sq  += __shfl_down_sync(0xffffffffu, sq, off);
        }
        if (lane == 0) {
            s_warp_sum[warp] = sum;
            s_warp_sq[warp]  = sq;
        }
        __syncthreads();
        if (warp == 0) {
            float tsum = (lane < nwarps) ? s_warp_sum[lane] : 0.0f;
            float tsq  = (lane < nwarps) ? s_warp_sq[lane]  : 0.0f;
            #pragma unroll
            for (int off = 16; off > 0; off >>= 1) {
                tsum += __shfl_down_sync(0xffffffffu, tsum, off);
                tsq  += __shfl_down_sync(0xffffffffu, tsq, off);
            }
            if (lane == 0) {
                const float mean = tsum / (float)N;
                float var = tsq / (float)N - mean * mean;
                var = var < 0.0f ? 0.0f : var;
                s_mean = mean;
                s_rstd = rsqrtf(var + eps);
            }
        }
        __syncthreads();
        const float mean = s_mean;
        const float rstd = s_rstd;
        // Pass 2a: normalize the staged head directly from shared memory.
        for (int64_t i = tid; i < stage4; i += nthr) {
            float4 xv = s_data[i];
            float4 wv = w[i];
            float4 bv = b[i];
            float4 o;
            o.x = (xv.x - mean) * rstd * wv.x + bv.x;
            o.y = (xv.y - mean) * rstd * wv.y + bv.y;
            o.z = (xv.z - mean) * rstd * wv.z + bv.z;
            o.w = (xv.w - mean) * rstd * wv.w + bv.w;
            yr[i] = o;
        }
        // Pass 2b: re-read only the unstaged tail from global memory.
        for (int64_t i = stage4 + tid; i < N4; i += nthr) {
            float4 xv = xr[i];
            float4 wv = w[i];
            float4 bv = b[i];
            float4 o;
            o.x = (xv.x - mean) * rstd * wv.x + bv.x;
            o.y = (xv.y - mean) * rstd * wv.y + bv.y;
            o.z = (xv.z - mean) * rstd * wv.z + bv.z;
            o.w = (xv.w - mean) * rstd * wv.w + bv.w;
            yr[i] = o;
        }
        __syncthreads();
    }
}

// Software grid-wide barrier (arrive-and-wait with sense reversal).
// Only used by kernels launched with cudaLaunchCooperativeKernel, which
// guarantees all blocks are co-resident, so spinning cannot deadlock.
__device__ __forceinline__ void coop_grid_barrier(unsigned int* __restrict__ bar,
                                                  unsigned int expected) {
    __threadfence();
    __syncthreads();
    if (threadIdx.x == 0) {
        volatile unsigned int* gen = bar + 1;
        const unsigned int g = *gen;
        if (atomicAdd(bar, 1u) == expected - 1u) {
            atomicExch(bar, 0u);
            __threadfence();
            atomicExch((unsigned int*)(bar + 1), g + 1u);
        } else {
            while (*gen == g) {
            }
        }
        __threadfence();
    }
    __syncthreads();
}
// Cooperative fused LayerNorm for few rows and large N: the whole
// persistent grid processes one row at a time. Pass 1 reduces the row
// while caching each thread's grid-stride slice in registers, a
// grid-wide barrier publishes the partials, every block redundantly
// folds them into mean/rstd using parity-buffered partials, and pass 2
// normalizes straight from the register cache. x is therefore read
// from DRAM exactly once, independent of L2 capacity, which minimizes
// DRAM traffic for this DRAM-bound workload. If a row slice does not
// fit in registers the kernel falls back to re-reading x from L2.
#define LN_COOP_MAXIT 16
__global__ void __launch_bounds__(256, 2) layernorm_coop_kernel(const float4* __restrict__ x,
                                      const float4* __restrict__ w,
                                      const float4* __restrict__ b,
                                      float4* __restrict__ y,
                                      float* __restrict__ p_sum,
                                      float* __restrict__ p_sq,
                                      float* __restrict__ stats,
                                      unsigned int* __restrict__ bar,
                                      int64_t N,
                                      int64_t N4,
                                      int64_t rows,
                                      float eps) {
    extern __shared__ float smem[];
    float* s_sum = smem;               // blockDim.x floats
    float* s_sq  = smem + blockDim.x;  // blockDim.x floats
    __shared__ float s_mean;
    __shared__ float s_rstd;
    const int tid = threadIdx.x;
    const int64_t gtid = (int64_t)blockIdx.x * blockDim.x + tid;
    const int64_t gstride = (int64_t)gridDim.x * blockDim.x;
    // True when every thread's slice of a row fits in the register
    // cache, so the normalize phase needs no global re-read of x.
    const bool reg_path = (N4 <= gstride * (int64_t)LN_COOP_MAXIT);
    for (int64_t row = 0; row < rows; ++row) {
        const float4* __restrict__ xr = x + row * N4;
        float4* __restrict__ yr = y + row * N4;
        const int64_t poff = (row & 1) * (int64_t)gridDim.x;
        float* __restrict__ ps = p_sum + poff;
        float* __restrict__ pq = p_sq + poff;
        // Pass 1: reduce this row, caching the slice in registers.
        float sum = 0.0f;
        float sq  = 0.0f;
        float4 xc[LN_COOP_MAXIT];
        if (reg_path) {
            #pragma unroll
            for (int k = 0; k < LN_COOP_MAXIT; ++k) {
                const int64_t i = gtid + (int64_t)k * gstride;
                if (i < N4) {
                    const float4 v = xr[i];
                    xc[k] = v;
                    sum += v.x + v.y + v.z + v.w;
                    sq  += v.x * v.x + v.y * v.y + v.z * v.z + v.w * v.w;
                }
            }
        } else {
            for (int64_t i = gtid; i < N4; i += gstride) {
                float4 v = xr[i];
                sum += v.x + v.y + v.z + v.w;
                sq  += v.x * v.x + v.y * v.y + v.z * v.z + v.w * v.w;
            }
        }
        s_sum[tid] = sum;
        s_sq[tid]  = sq;
        __syncthreads();
        for (int s = blockDim.x >> 1; s > 0; s >>= 1) {
            if (tid < s) {
                s_sum[tid] += s_sum[tid + s];
                s_sq[tid]  += s_sq[tid + s];
            }
            __syncthreads();
        }
        if (tid == 0) {
            ps[blockIdx.x] = s_sum[0];
            pq[blockIdx.x] = s_sq[0];
        }
        coop_grid_barrier(bar, gridDim.x);
        // Redundantly fold the small partial arrays in every block. This
        // removes the second grid-wide barrier and block-0 serialization.
        float tsum = 0.0f;
        float tsq  = 0.0f;
        for (unsigned int i = tid; i < gridDim.x; i += blockDim.x) {
            tsum += ps[i];
            tsq  += pq[i];
        }
        s_sum[tid] = tsum;
        s_sq[tid]  = tsq;
        __syncthreads();
        for (int s = blockDim.x >> 1; s > 0; s >>= 1) {
            if (tid < s) {
                s_sum[tid] += s_sum[tid + s];
                s_sq[tid]  += s_sq[tid + s];
            }
            __syncthreads();
        }
        if (tid == 0) {
            const float mean = s_sum[0] / (float)N;
            float var = s_sq[0] / (float)N - mean * mean;
            var = var < 0.0f ? 0.0f : var;
            s_mean = mean;
            s_rstd = rsqrtf(var + eps);
        }
        __syncthreads();
        // Pass 2: normalize from the register cache (fallback path
        // re-reads x, which then comes back from L2).
        const float mean = s_mean;
        const float rstd = s_rstd;
        if (reg_path) {
            #pragma unroll
            for (int k = 0; k < LN_COOP_MAXIT; ++k) {
                const int64_t i = gtid + (int64_t)k * gstride;
                if (i < N4) {
                    const float4 xv = xc[k];
                    const float4 wv = w[i];
                    const float4 bv = b[i];
                    float4 o;
                    o.x = (xv.x - mean) * rstd * wv.x + bv.x;
                    o.y = (xv.y - mean) * rstd * wv.y + bv.y;
                    o.z = (xv.z - mean) * rstd * wv.z + bv.z;
                    o.w = (xv.w - mean) * rstd * wv.w + bv.w;
                    __stcs(yr + i, o);
                }
            }
        } else {
            for (int64_t i = gtid; i < N4; i += gstride) {
                float4 xv = xr[i];
                float4 wv = w[i];
                float4 bv = b[i];
                float4 o;
                o.x = (xv.x - mean) * rstd * wv.x + bv.x;
                o.y = (xv.y - mean) * rstd * wv.y + bv.y;
                o.z = (xv.z - mean) * rstd * wv.z + bv.z;
                o.w = (xv.w - mean) * rstd * wv.w + bv.w;
                __stcs(yr + i, o);
            }
        }
    }
}
torch::Tensor layernorm_forward(torch::Tensor x,
                                torch::Tensor w,
                                torch::Tensor b,
                                double eps,
                                int64_t normalized_size) {
    TORCH_CHECK(x.is_cuda() && w.is_cuda() && b.is_cuda(),
                "All tensors must be CUDA tensors");
    TORCH_CHECK(x.scalar_type() == at::kFloat, "x must be float32");
    auto y = torch::empty_like(x);
    const int64_t rows = x.numel() / normalized_size;
    const int64_t N = normalized_size;
    const int threads = 256;
    const int sms = at::cuda::getCurrentDeviceProperties()->multiProcessorCount;
    const size_t shmem = 2 * threads * sizeof(float);
    auto stream = at::cuda::getCurrentCUDAStream();
    // Fused single-kernel path (the workload is DRAM bound and x is
    // otherwise read twice): one block per row stages the head of the
    // row in opt-in shared memory while accumulating sum/sum-of-squares,
    // then normalizes from shared memory, cutting global-memory traffic.
    if ((N & 3) == 0) {
        auto* fprop = at::cuda::getCurrentDeviceProperties();
        const int64_t N4f = N >> 2;
        int64_t target = ((int64_t)fprop->sharedMemPerMultiprocessor / 2) - 2048;
        if (target > (int64_t)fprop->sharedMemPerBlockOptin)
            target = (int64_t)fprop->sharedMemPerBlockOptin;
        target &= ~(int64_t)15;
        int64_t stage4 = target / (int64_t)sizeof(float4);
        if (stage4 > N4f) stage4 = N4f;
        if (stage4 >= 4096 && rows >= (int64_t)sms) {
            const int fthreads = 512;
            const size_t fsmem = (size_t)stage4 * sizeof(float4);
            cudaFuncSetAttribute(layernorm_fused_smem_kernel,
                                 cudaFuncAttributeMaxDynamicSharedMemorySize,
                                 (int)fsmem);
            int fblocks_per_sm = 0;
            cudaOccupancyMaxActiveBlocksPerMultiprocessor(
                &fblocks_per_sm, layernorm_fused_smem_kernel, fthreads, fsmem);
            if (fblocks_per_sm < 1) fblocks_per_sm = 1;
            int64_t fgrid = (int64_t)sms * fblocks_per_sm;
            if (fgrid > rows) fgrid = rows;
            layernorm_fused_smem_kernel<<<(unsigned int)fgrid, fthreads, fsmem, stream>>>(
                reinterpret_cast<const float4*>(x.data_ptr<float>()),
                reinterpret_cast<const float4*>(w.data_ptr<float>()),
                reinterpret_cast<const float4*>(b.data_ptr<float>()),
                reinterpret_cast<float4*>(y.data_ptr<float>()),
                N,
                N4f,
                rows,
                stage4,
                (float)eps);
            return y;
        }
    }
    // Cooperative single-launch path for few rows with a large row size:
    // one persistent grid processes one row at a time with a software
    // grid-wide barrier between the reduce and normalize phases. Because
    // the same thread slice is reduced and then normalized, the row is
    // re-read from L2 instead of DRAM, roughly halving DRAM traffic for
    // this DRAM-bound workload. cudaLaunchCooperativeKernel guarantees
    // co-residency, so the barrier cannot deadlock.
