// Only used by kernels launched with cudaLaunchCooperativeKernel, which
// guarantees all blocks are co-resident, so spinning cannot deadlock.
__device__ __forceinline__ void coop_grid_barrier(unsigned int* __restrict__ bar,
                                                  unsigned int expected) {
    __threadfence();
    __syncthreads();
