    s_sum[threadIdx.x] = sum;
    s_sq[threadIdx.x]  = sq;
    __syncthreads();
    for (int s = blockDim.x >> 1; s > 0; s >>= 1) {
        if (threadIdx.x < s) {
            s_sum[threadIdx.x] += s_sum[threadIdx.x + s];
            s_sq[threadIdx.x]  += s_sq[threadIdx.x + s];
        }
        __syncthreads();
    }
    if (threadIdx.x == 0) {
        p_sum[blockIdx.x] = s_sum[0];
        p_sq[blockIdx.x]  = s_sq[0];
    }
}
// Stage 2: each block cheaply re-reduces the small partial arrays of
// its row to get mean / rstd, then normalizes its own chunk.
__global__ void layernorm_normalize_kernel(const float* __restrict__ x,
                                           const float* __restrict__ w,
                                           const float* __restrict__ b,
                                           float* __restrict__ y,
                                           const float* __restrict__ p_sum,
                                           const float* __restrict__ p_sq,
                                           int64_t N,
                                           int64_t chunk,
                                           int64_t nchunks,
                                           float eps) {
    extern __shared__ float smem[];
    float* s_sum = smem;               // blockDim.x floats
    float* s_sq  = smem + blockDim.x;  // blockDim.x floats
    __shared__ float s_mean;
    __shared__ float s_rstd;
    const int64_t row = blockIdx.x / nchunks;
    const int64_t c   = blockIdx.x % nchunks;
    const float* __restrict__ ps = p_sum + row * nchunks;
    const float* __restrict__ pq = p_sq  + row * nchunks;
    float sum = 0.0f;
    float sq  = 0.0f;
    for (int64_t i = threadIdx.x; i < nchunks; i += blockDim.x) {
        sum += ps[i];
        sq  += pq[i];
    }
    s_sum[threadIdx.x] = sum;
    s_sq[threadIdx.x]  = sq;
    __syncthreads();
    for (int s = blockDim.x >> 1; s > 0; s >>= 1) {
        if (threadIdx.x < s) {
            s_sum[threadIdx.x] += s_sum[threadIdx.x + s];
            s_sq[threadIdx.x]  += s_sq[threadIdx.x + s];
        }
        __syncthreads();
    }
    if (threadIdx.x == 0) {
        const float mean = s_sum[0] / (float)N;
        float var = s_sq[0] / (float)N - mean * mean;
        var = var < 0.0f ? 0.0f : var;
        s_mean = mean;
        s_rstd = rsqrtf(var + eps);
    }
    __syncthreads();
    const float mean = s_mean;
    const float rstd = s_rstd;
    const int64_t start = c * chunk;
    int64_t end = start + chunk;
    if (end > N) end = N;
    const float* __restrict__ xr = x + row * N;
    float* __restrict__ yr = y + row * N;
    for (int64_t i = start + threadIdx.x; i < end; i += blockDim.x) {
        yr[i] = (xr[i] - mean) * rstd * w[i] + b[i];
    }
}
// Stage 2 vectorized: float4 loads/stores for x, w, b and y.
__global__ void layernorm_normalize_vec4_kernel(const float4* __restrict__ x,
                                                const float4* __restrict__ w,
                                                const float4* __restrict__ b,
                                                float4* __restrict__ y,
                                                const float* __restrict__ p_sum,
                                                const float* __restrict__ p_sq,
                                                int64_t N,
                                                int64_t N4,
                                                int64_t chunk,
                                                int64_t nchunks,
                                                float eps) {
    extern __shared__ float smem[];
    float* s_sum = smem;               // blockDim.x floats
    float* s_sq  = smem + blockDim.x;  // blockDim.x floats
    __shared__ float s_mean;
    __shared__ float s_rstd;
    const int64_t row = blockIdx.x / nchunks;
    const int64_t c   = blockIdx.x % nchunks;
    const float* __restrict__ ps = p_sum + row * nchunks;
    const float* __restrict__ pq = p_sq  + row * nchunks;
    float sum = 0.0f;
    float sq  = 0.0f;
    for (int64_t i = threadIdx.x; i < nchunks; i += blockDim.x) {
        sum += ps[i];
        sq  += pq[i];
    }
    s_sum[threadIdx.x] = sum;
    s_sq[threadIdx.x]  = sq;
    __syncthreads();
    for (int s = blockDim.x >> 1; s > 0; s >>= 1) {
        if (threadIdx.x < s) {
            s_sum[threadIdx.x] += s_sum[threadIdx.x + s];
            s_sq[threadIdx.x]  += s_sq[threadIdx.x + s];
        }
        __syncthreads();
    }
    if (threadIdx.x == 0) {
        const float mean = s_sum[0] / (float)N;
        float var = s_sq[0] / (float)N - mean * mean;
        var = var < 0.0f ? 0.0f : var;
        s_mean = mean;
        s_rstd = rsqrtf(var + eps);
    }
    __syncthreads();
    const float mean = s_mean;
    const float rstd = s_rstd;
    const int64_t start = c * chunk;
    int64_t end = start + chunk;
    if (end > N4) end = N4;
    const float4* __restrict__ xr = x + row * N4;
    float4* __restrict__ yr = y + row * N4;
    for (int64_t i = start + threadIdx.x; i < end; i += blockDim.x) {
        float4 xv = xr[i];
        float4 wv = w[i];
        float4 bv = b[i];
        float4 o;
        o.x = (xv.x - mean) * rstd * wv.x + bv.x;
        o.y = (xv.y - mean) * rstd * wv.y + bv.y;
        o.z = (xv.z - mean) * rstd * wv.z + bv.z;
        o.w = (xv.w - mean) * rstd * wv.w + bv.w;
        yr[i] = o;
    }
}

torch::Tensor layernorm_forward(torch::Tensor x,
                                torch::Tensor w,
                                torch::Tensor b,
                                double eps,
                                int64_t normalized_size) {
    TORCH_CHECK(x.is_cuda() && w.is_cuda() && b.is_cuda(),
                "All tensors must be CUDA tensors");
    TORCH_CHECK(x.scalar_type() == at::kFloat, "x must be float32");
    auto y = torch::empty_like(x);
    const int64_t rows = x.numel() / normalized_size;
    const int64_t N = normalized_size;
    const int threads = 256;
    const int sms = at::cuda::getCurrentDeviceProperties()->multiProcessorCount;
    const size_t shmem = 2 * threads * sizeof(float);
    auto stream = at::cuda::getCurrentCUDAStream();
    if ((N & 3) == 0) {
        // Vectorized path: chunk the row in units of float4 (16B) so both
        // kernels use wide, fully-coalesced global-memory transactions.
        const int64_t N4 = N >> 2;
        int64_t chunks = ((int64_t)sms * 4 + rows - 1) / rows;
        const int64_t max_chunks = (N4 + threads - 1) / threads;
        if (chunks > max_chunks) chunks = max_chunks;
        if (chunks < 1) chunks = 1;
        const int64_t chunk = (N4 + chunks - 1) / chunks;
        chunks = (N4 + chunk - 1) / chunk;
        auto p_sum = torch::empty({rows * chunks}, x.options());
        auto p_sq  = torch::empty({rows * chunks}, x.options());
        const dim3 grid((unsigned int)(rows * chunks));
        layernorm_partial_vec4_kernel<<<grid, threads, shmem, stream>>>(
            reinterpret_cast<const float4*>(x.data_ptr<float>()),
            p_sum.data_ptr<float>(),
            p_sq.data_ptr<float>(),
            N4,
            chunk,
            chunks);
        layernorm_normalize_vec4_kernel<<<grid, threads, shmem, stream>>>(
            reinterpret_cast<const float4*>(x.data_ptr<float>()),
            reinterpret_cast<const float4*>(w.data_ptr<float>()),
            reinterpret_cast<const float4*>(b.data_ptr<float>()),
            reinterpret_cast<float4*>(y.data_ptr<float>()),
            p_sum.data_ptr<float>(),
            p_sq.data_ptr<float>(),
            N,
            N4,
            chunk,
            chunks,
            (float)eps);
    } else {
        // Scalar fallback for rows whose length is not divisible by 4.
        int64_t chunks = ((int64_t)sms * 4 + rows - 1) / rows;
        const int64_t max_chunks = (N + threads - 1) / threads;
        if (chunks > max_chunks) chunks = max_chunks;
        if (chunks < 1) chunks = 1;
        const int64_t chunk = (N + chunks - 1) / chunks;
        chunks = (N + chunk - 1) / chunk;
        auto p_sum = torch::empty({rows * chunks}, x.options());
        auto p_sq  = torch::empty({rows * chunks}, x.options());
        const dim3 grid((unsigned int)(rows * chunks));
        layernorm_partial_kernel<<<grid, threads, shmem, stream>>>(
            x.data_ptr<float>(),
            p_sum.data_ptr<float>(),
            p_sq.data_ptr<float>(),
            N,
            chunk,
            chunks);
        layernorm_normalize_kernel<<<grid, threads, shmem, stream>>>(
            x.data_ptr<float>(),
            w.data_ptr<float>(),
            b.data_ptr<float>(),
            y.data_ptr<float>(),
            p_sum.data_ptr<float>(),
            p_sq.data_ptr<float>(),
            N,
            chunk,
            chunks,
            (float)eps);
    }
    return y;
}
