class ModelNew(nn.Module):
    """
    LayerNorm implemented with a custom fused CUDA kernel.
    """

    def __init__(self, normalized_shape: tuple):
        super(ModelNew, self).__init__()
        self.normalized_shape = tuple(normalized_shape)
        self.normalized_size = 1
        for d in self.normalized_shape:
            self.normalized_size *= d
        self.eps = 1e-5
        self.weight = nn.Parameter(torch.ones(self.normalized_shape))
        self.bias = nn.Parameter(torch.zeros(self.normalized_shape))

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        if not x.is_cuda:
            x = x.cuda()
        x = x.contiguous().float()
        w = self.weight
        b = self.bias
        if not w.is_cuda:
            w = w.cuda()
            b = b.cuda()
        w = w.contiguous().view(-1)
        b = b.contiguous().view(-1)
        return _ln_mod.layernorm_forward(
            x, w, b, self.eps, self.normalized_size
        )
